10	/// Run lint rules over an [`ExceptHandler`] syntax node.
11	pub(crate) fn except_handler(except_handler: &ExceptHandler, checker: &Checker) {
12	    match except_handler {
13	        ExceptHandler::ExceptHandler(ast::ExceptHandlerExceptHandler {
14	            type_,
15	            name,
16	            body,
17	            range: _,
18	            node_index: _,
19	        }) => {
20	            if checker.is_rule_enabled(Rule::BareExcept) {
21	                pycodestyle::rules::bare_except(checker, type_.as_deref(), body, except_handler);
22	            }
23	            if checker.is_rule_enabled(Rule::RaiseWithoutFromInsideExcept) {
24	                flake8_bugbear::rules::raise_without_from_inside_except(
25	                    checker,
26	                    name.as_deref(),
27	                    body,
28	                );
29	            }
30	            if checker.is_rule_enabled(Rule::BlindExcept) {
31	                flake8_blind_except::rules::blind_except(
32	                    checker,
33	                    type_.as_deref(),
34	                    name.as_deref(),
35	                    body,
36	                );
37	            }
38	            if checker.is_rule_enabled(Rule::TryExceptPass) {
39	                flake8_bandit::rules::try_except_pass(
40	                    checker,
41	                    except_handler,
42	                    type_.as_deref(),
43	                    body,
44	                    checker.settings().flake8_bandit.check_typed_exception,
45	                );
46	            }
47	            if checker.is_rule_enabled(Rule::TryExceptContinue) {
48	                flake8_bandit::rules::try_except_continue(
49	                    checker,
50	                    except_handler,
51	                    type_.as_deref(),
52	                    body,
53	                    checker.settings().flake8_bandit.check_typed_exception,
54	                );
55	            }
56	            if checker.is_rule_enabled(Rule::ExceptWithEmptyTuple) {
57	                flake8_bugbear::rules::except_with_empty_tuple(checker, except_handler);
58	            }
59	            if checker.is_rule_enabled(Rule::ExceptWithNonExceptionClasses) {
60	                flake8_bugbear::rules::except_with_non_exception_classes(checker, except_handler);
61	            }
62	            if checker.is_rule_enabled(Rule::BinaryOpException) {
63	                pylint::rules::binary_op_exception(checker, except_handler);
64	            }
65	            if let Some(name) = name {
66	                if checker.is_rule_enabled(Rule::AmbiguousVariableName) {
67	                    pycodestyle::rules::ambiguous_variable_name(
68	                        checker,
69	                        name.as_str(),
70	                        name.range(),
71	                    );
72	                }
73	                if checker.is_rule_enabled(Rule::BuiltinVariableShadowing) {
74	                    flake8_builtins::rules::builtin_variable_shadowing(checker, name, name.range());
75	                }
76	            }
77	        }
78	    }
